import { Chain } from '@railgun-community/shared-models';
import { BroadcasterConfig } from '../models/broadcaster-config.js';

export const contentTopics = {
  default: () => `/${BroadcasterConfig.contentTopicApp}/v2/default/json`,
  fees: (chain: Chain) =>
    `/${BroadcasterConfig.contentTopicApp}/v2/${chain.type}-${chain.id}-fees/json`,
  transact: (chain: Chain) =>
    `/${BroadcasterConfig.contentTopicApp}/v2/${chain.type}-${chain.id}-transact/json`,
  transactResponse: (chain: Chain) =>
    `/${BroadcasterConfig.contentTopicApp}/v2/${chain.type}-${chain.id}-transact-response/json`,
  metrics: () => `/${BroadcasterConfig.contentTopicApp}/v2/metrics/json`,
  encrypted: (topic: string) =>
    `/${BroadcasterConfig.contentTopicApp}/v2/encrypted-${topic}/json`,
};
